import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';

// Exercise only an address generated by this test in the private Mailpit inbox.
export async function exerciseAccount(page) {
  const inbox = process.env.CFO_MAILBOX_URL || 'http://127.0.0.1:8025';
  const id = randomUUID(),
    password = randomUUID(),
    updatedPassword = randomUUID();
  const email = id + '@example.invalid',
    newEmail = id + '-new@example.invalid';
  const click = (name) =>
    page.getByRole('button', { name, exact: true }).click();
  const field = (name, value) =>
    page.getByLabel(name, { exact: true }).fill(value);
  async function confirmClick(name, confirmation) {
    await click(name);
    await click(confirmation);
  }
  async function code(address, subject) {
    await page.getByLabel('Email code', { exact: true }).waitFor();
    const query = new URLSearchParams({
      query: 'to:' + address + ' subject:"' + subject + '"',
    });
    for (let i = 0; i < 80; i++) {
      const res = await fetch(inbox + '/api/v1/search?' + query);
      assert(res.ok);
      const msg = (await res.json()).messages.find(
        (m) =>
          m.To.some((to) => to.Address === address) &&
          m.Subject.endsWith(subject),
      );
      if (msg) {
        const full = await (
          await fetch(inbox + '/api/v1/message/' + msg.ID)
        ).json();
        return full.Text.match(/^([0-9]{6})\r?$/m)[1];
      }
      await new Promise((resolve) => setTimeout(resolve, 250));
    }
    throw Error('Account mail did not arrive');
  }
  async function login(address, secret) {
    await field('Email', address);
    await field('Password', secret);
    await click('Sign in');
    await page.locator('.user-chip').waitFor();
  }
  await click('Polski');
  await page
    .getByRole('heading', { name: 'Zaloguj się', exact: true })
    .waitFor();
  assert.equal(
    await page
      .getByRole('button', { name: 'Polski' })
      .getAttribute('aria-pressed'),
    'true',
  );
  await click('English');
  await click('Create account');
  await field('First name', 'Anna');
  await field('Last name', 'Nowak');
  await field('Email', email);
  await field('Password', password);
  await click('Create account');
  const originalCode = await code(email, 'Verify your email');
  const resent = page.waitForResponse((response) =>
    response.url().endsWith('/account/resend'),
  );
  await click('Resend code');
  assert.equal((await (await resent).json()).delivery, 'preview');
  await field('Email code', originalCode);
  await click('Verify email');
  await page
    .getByRole('alert')
    .filter({ hasText: 'Invalid or expired code' })
    .waitFor();
  const latestCode = await code(email, 'Verify your email');
  assert.notEqual(latestCode, originalCode);
  await field('Email code', latestCode);
  await click('Verify email');
  await login(email, password);
  await page.reload();
  await page.locator('.user-chip').click();
  await field('First name', 'Ada');
  await click('Save');
  await click('Back to editing');
  assert.equal(await page.getByLabel('First name', { exact: true }).inputValue(), 'Ada');
  await confirmClick('Save', 'Confirm changes');
  await page.locator('.user-chip').filter({ hasText: 'Ada Nowak' }).waitFor();
  await field('Email', newEmail);
  await field('Current password', password);
  await confirmClick('Save', 'Send code');
  await field('Email code', await code(newEmail, 'Confirm your new email'));
  await field('Current password', password);
  await click('Confirm new email');
  await page.locator('input[name=email]').waitFor();
  assert.equal(await page.getByLabel('Email', { exact: true }).inputValue(), newEmail);
  await click('Log out');
  await click('Forgot password?');
  await field('Email', newEmail);
  await click('Send reset code');
  await field('Email code', await code(newEmail, 'Reset your password'));
  await click('Verify reset code');
  await field('New password', updatedPassword);
  await field('Confirm new password', updatedPassword);
  await click('Set new password');
  await login(newEmail, updatedPassword);
  console.log(
    'Email activation, persistent login, name, email change, logout and reset verified',
  );
  return async () => {
    await page.locator('.user-chip').click();
    await click('Delete my account');
    await click('Cancel');
    await click('Delete my account');
    await field('Current password', updatedPassword);
    await confirmClick('Delete my account', 'Delete my account');
    await page.getByRole('heading', { name: 'Sign in', exact: true }).waitFor();
    assert.equal(
      await page.evaluate(async () => (await fetch('/api/workspace')).status),
      401,
    );
  };
}
